<script setup lang="ts">
import { computed,onMounted,ref } from 'vue'
import { useRoute } from 'vue-router'
import { api,errorText } from '../api'
import { useAuth } from '../stores/auth'
import { allowed,date,statuses,listItems,overdue } from '../domain'
import type { Row } from '../domain'
import { useLoad,usePoll } from '../composables'
import PageState from '../components/PageState.vue'
import StatusBadge from '../components/StatusBadge.vue'
import ActionDialog from '../components/ActionDialog.vue'
import WorkItems from '../components/WorkItems.vue'
const auth=useAuth(),route=useRoute(),task=ref<Row|null>(null),tab=ref('work'),{loading,error,run}=useLoad(),action=ref(''),actionRow=ref<Row>({}),resource=ref('tasks'),dialog=ref(false),comment=ref(''),mentions=ref<string[]>([]),users=ref<Row[]>([]),busy=ref(false),operationError=ref(''),uploadSub=ref(''),versions=ref<Row[]>([]),versionsOpen=ref(false)
const taskActions=['confirm-assign','summarize','accept','reject','deadline','urge','cancel'],subActions=['receive','assign','progress','submit','withdraw','extend','transfer']
const requests=computed(()=>[...(task.value?.deadlineRequests??[]).map((r:Row)=>({...r,kind:'延期申请',resource:'deadline-requests'})),...(task.value?.collaborationRequests??[]).map((r:Row)=>({...r,kind:'协办确认',resource:'collaborations'}))])
function load(quiet=false){if(quiet){api.get('/tasks/'+encodeURIComponent(String(route.params.id))).then(v=>task.value=v).catch(e=>operationError.value=errorText(e));return}run(()=>api.get('/tasks/'+encodeURIComponent(String(route.params.id))),v=>task.value=v)}
function act(a:string,row:Row,res='tasks'){action.value=a;actionRow.value=row;resource.value=res;dialog.value=true;operationError.value=''}
async function sendComment(){if(!comment.value.trim()||busy.value)return;busy.value=true;operationError.value='';try{await api.post(`/tasks/${task.value!.id}/comments`,{content:comment.value,mentions:mentions.value});comment.value='';mentions.value=[];load(true)}catch(e){operationError.value=errorText(e)}finally{busy.value=false}}
async function upload(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;busy.value=true;operationError.value='';try{const data=new FormData();data.append('file',file);data.append('taskId',task.value!.id);if(uploadSub.value)data.append('subTaskId',uploadSub.value);await api.upload(data);load(true)}catch(e){operationError.value=errorText(e)}finally{busy.value=false;input.value=''}}
async function fileAction(file:Row,op:string){operationError.value='';try{if(op==='versions'){versions.value=listItems(await api.get(`/attachments/${file.id}/versions`));versionsOpen.value=true}else if(op==='preview'){await api.preview(`/attachments/${file.id}/preview`)}else await api.download(`/attachments/${file.id}/download`,file.originalName||file.filename||file.name||'attachment')}catch(e){operationError.value=errorText(e)}}
onMounted(()=>{load();api.get('/organization/users').then(v=>users.value=listItems(v)).catch(()=>{})});usePoll(()=>{if(!dialog.value&&!busy.value&&task.value)load(true)})
</script>
<template>
<div class="backline"><router-link to="/tasks">← 任务中心</router-link><span>任务详情</span></div><PageState :loading="loading" :error="error" @retry="load()">
<template v-if="task">
<section class="detail-hero panel"><div class="row-between"><p class="eyebrow">{{ task.code }} · 版本 {{ task.version }}</p><StatusBadge :status="task.status" :overdue="overdue(task)"/></div><h1>{{ task.title }}</h1><div class="detail-meta"><span>所属公司 <b>{{ task.companyName||task.companyId }}</b></span><span>主办部门 <b>{{ task.hostDeptName||task.hostDeptId }}</b></span><span>截止 <b>{{ date(task.deadline) }}</b></span><span>优先级 <b>{{ ({NORMAL:'普通',HIGH:'高',URGENT:'紧急',LOW:'低'} as Row)[task.priority]||task.priority }}</b></span></div><div class="action-strip"><template v-for="a in taskActions" :key="a"><el-button v-if="allowed(task,a)&&(!auth.me?.permissions||auth.me.permissions.includes('TASK_UPDATE'))" :type="['confirm-assign','accept','summarize'].includes(a)?'primary':a==='cancel'?'danger':'default'" :plain="a==='cancel'" @click="act(a,task)">{{ ({'confirm-assign':'确认分配',summarize:'汇总上报',accept:'验收通过',reject:'退回修改',deadline:'调整截止',urge:'催办',cancel:'取消任务'} as Row)[a] }}</el-button></template></div></section><el-alert v-if="operationError" :title="operationError" type="error" :closable="true" show-icon @close="operationError=''"/><div class="detail-layout">
<section class="panel detail-main">
<el-tabs v-model="tab">
<el-tab-pane label="任务与执行" name="work"><h2>任务要求</h2><p class="pre-wrap task-content">{{ task.content }}</p><div class="section-rule"/><div class="panel-heading"><h2>部门执行</h2><span class="muted">{{ task.subTasks?.length||0 }} 个责任部门</span></div><el-empty v-if="!task.subTasks?.length" description="尚无执行子任务"/><article v-for="s in task.subTasks||[]" :key="s.id" class="subtask-card"><div class="row-between"><div><span class="dept-role">{{ s.role==='HOST'||s.deptId===task.hostDeptId?'主办':'协办' }}</span><b>{{ s.deptName||s.deptId }}</b></div><StatusBadge :status="s.status" :overdue="overdue(s)"/></div><p class="muted">负责人 {{ s.ownerName||s.ownerId||'待分派' }} · 截止 {{ date(s.deadline||task.deadline) }} · 版本 {{ s.version }}</p><el-progress :percentage="Math.min(100,Math.max(0,Number(s.percent??s.progress??0)))" :stroke-width="7"/><p v-if="s.summary" class="pre-wrap">成果：{{ s.summary }}</p><div class="subtask-actions"><template v-for="a in subActions" :key="a"><el-button v-if="allowed(s,a)&&(!auth.me?.permissions||auth.me.permissions.includes('TASK_UPDATE'))" size="small" :type="a==='submit'?'primary':'default'" @click="act(a,s,'sub-tasks')">{{ ({receive:'接收任务',assign:'分派人员',progress:'更新进度',submit:'提交成果',withdraw:'撤回提交',extend:'申请延期',transfer:'转交'} as Row)[a] }}</el-button></template></div></article><WorkItems :task="task" @changed="load(true)"/></el-tab-pane>
<el-tab-pane label="进度记录" name="progress"><el-empty v-if="!task.progress?.length" description="暂无进度记录"/><el-timeline><el-timeline-item v-for="p in task.progress||[]" :key="p.id" :timestamp="date(p.createdAt)"><b>{{ p.authorName||p.userName||p.deptName||'进度更新' }} · {{ p.percent }}%</b><p class="pre-wrap">{{ p.note }}</p></el-timeline-item></el-timeline></el-tab-pane>
<el-tab-pane v-if="!auth.me?.permissions||auth.me.permissions.includes('ATTACHMENTS')" label="附件与版本" name="files"><div v-if="allowed(task,'upload')" class="upload-bar"><el-select v-model="uploadSub" clearable placeholder="关联子任务（可选）"><el-option v-for="s in task.subTasks||[]" :key="s.id" :label="s.deptName||String(s.deptId)" :value="s.id"/></el-select><label class="upload-button" :class="{disabled:busy}">上传附件<input type="file" :disabled="busy" @change="upload"/></label></div><p class="notice">附件通过服务端安全检测后方可下载。隔离中的文件不可预览。</p><el-empty v-if="!task.attachments?.length" description="暂无附件"/><article v-for="f in task.attachments||[]" :key="f.id" class="attachment-row"><div><b>{{ f.originalName||f.filename||f.name }}</b><p class="muted">{{ date(f.createdAt) }} · {{ f.size?Math.ceil(f.size/1024)+' KB':'' }} · {{ statuses[f.scanStatus||f.status]||f.scanStatus||f.status||'—' }}</p></div><div><el-button v-if="allowed(f,'download')" text @click="fileAction(f,'download')">下载</el-button><el-button v-if="allowed(f,'preview')" text @click="fileAction(f,'preview')">预览</el-button><el-button v-if="allowed(f,'versions')" text @click="fileAction(f,'versions')">版本</el-button></div></article></el-tab-pane>
<el-tab-pane :label="'申请与协同 ('+requests.length+')'" name="requests"><el-empty v-if="!requests.length" description="暂无待处理申请"/><article v-for="r in requests" :key="r.resource+r.id" class="request-card"><div class="row-between"><b>{{ r.kind }} · {{ r.deptName||r.requesterName||r.id }}</b><StatusBadge :status="r.status"/></div><p class="pre-wrap">{{ r.reason||r.message }}</p><p v-if="r.deadline">申请延期至 {{ date(r.deadline) }}</p><el-button v-if="allowed(r,r.resource==='collaborations'?'accept':'approve')" size="small" type="primary" @click="act(r.resource==='collaborations'?'accept':'approve',r,r.resource)">同意</el-button><el-button v-if="allowed(r,'reject')" size="small" @click="act('reject',r,r.resource)">拒绝</el-button></article></el-tab-pane>
<el-tab-pane label="操作时间线" name="timeline"><el-empty v-if="!task.timeline?.length" description="暂无历史记录"/><el-timeline><el-timeline-item v-for="t in task.timeline||[]" :key="t.id" :timestamp="date(t.createdAt)"><strong>{{ t.actionName||t.action||t.type }} · {{ t.operatorName||t.actorName||t.userName||'' }}</strong><p class="pre-wrap">{{ t.description||t.reason||t.content }}</p></el-timeline-item></el-timeline></el-tab-pane>
</el-tabs>
</section>
<aside class="panel comments-panel"><h2>沟通记录 <small>{{ task.comments?.length||0 }}</small></h2><p class="muted">让决策与执行信息持续同步</p><el-empty v-if="!task.comments?.length" description="暂无沟通记录" :image-size="60"/><article v-for="c in task.comments||[]" :key="c.id" class="comment-item"><div class="row-between"><b>{{ c.authorName||c.userName||'成员' }}</b><small>{{ date(c.createdAt) }}</small></div><p class="pre-wrap">{{ c.content }}</p></article><el-form v-if="allowed(task,'comment')&&(!auth.me?.permissions||auth.me.permissions.includes('TASK_UPDATE'))" label-position="top" @submit.prevent="sendComment"><el-form-item label="发表意见"><el-input v-model="comment" type="textarea" :rows="4" maxlength="2000" placeholder="补充说明或同步进展"/></el-form-item><el-form-item label="提醒相关人员"><el-select v-model="mentions" multiple filterable placeholder="选择 @ 人员"><el-option v-for="u in users" :key="u.id" :value="u.id" :label="u.name"/></el-select></el-form-item><el-button type="primary" native-type="submit" :loading="busy" :disabled="!comment.trim()">发送意见</el-button></el-form></aside>
</div><ActionDialog v-model="dialog" :action="action" :row="actionRow" :resource="resource" @done="load(true)"/><el-dialog v-model="versionsOpen" title="附件版本记录" width="640px"><el-empty v-if="!versions.length" description="暂无版本记录"/><article v-for="v in versions" :key="v.id" class="attachment-row"><div><b>版本 {{ v.version }} · {{ v.originalName||v.name }}</b><p>{{ date(v.createdAt) }} · {{ statuses[v.scanStatus||v.status]||v.scanStatus||v.status||'—' }}</p></div><el-button v-if="allowed(v,'download')" @click="fileAction(v,'download')">下载</el-button></article></el-dialog>
</template>
</PageState>
</template>
